{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"pygments_lexer":"ipython3","nbconvert_exporter":"python","version":"3.6.4","file_extension":".py","codemirror_mode":{"name":"ipython","version":3},"name":"python","mimetype":"text/x-python"},"kaggle":{"accelerator":"none","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# app.py\nimport streamlit as st\nfrom qa_bot import answer_question  # Import the QA function\nfrom text_summarizer import summarize_text  # Import the summarizer function\n\n# Initialize the Streamlit app with a title\nst.set_page_config(page_title=\"Text Analysis Bot\", layout=\"centered\")\nst.title(\"Text Analysis Bot\")\n\n# Initialize session state for navigation and variables\nif 'page' not in st.session_state:\n    st.session_state.page = 'home'\nif 'context' not in st.session_state:\n    st.session_state.context = ''\nif 'summarized_text' not in st.session_state:\n    st.session_state.summarized_text = ''\nif 'question' not in st.session_state:\n    st.session_state.question = ''\nif 'answer' not in st.session_state:\n    st.session_state.answer = ''\n\n# Navigation buttons for page switching\ndef go_home():\n    st.session_state.page = 'home'\n    st.session_state.context = ''\n    st.session_state.summarized_text = ''\n    st.session_state.question = ''\n    st.session_state.answer = ''\n\ndef go_summary():\n    st.session_state.page = 'summary'\n\n# Home Page\nif st.session_state.page == 'home':\n    st.subheader(\"Enter Paragraph for Text Analysis\")\n    \n    # Context input area with word and character count\n    context = st.text_area(\"Enter the context paragraph:\", value=st.session_state.context, height=200)\n    st.session_state.context = context  # Update session state\n\n    # Word and character count\n    word_count = len(context.split())\n    char_count = len(context)\n    st.write(f\"Word Count: {word_count}, Character Count: {char_count}\")\n    \n    # Summarize button (appears when character count is at least 2000)\n    if char_count >= 2000:\n        if st.button(\"Generate Abstract Summary\"):\n            st.session_state.summarized_text = summarize_text(context)\n            go_summary()  # Switch to summary page\n\n    # QA submit button\n    if st.button(\"Submit for QA\"):\n        st.write(\"Enter your question below.\")\n        st.session_state.page = 'qa'\n\n# Summary Page\nelif st.session_state.page == 'summary':\n    st.subheader(\"Summarized Text\")\n    st.write(st.session_state.summarized_text)\n    if st.button(\"Home\"):\n        go_home()\n\n# QA Page\nelif st.session_state.page == 'qa':\n    st.subheader(\"Ask a Question\")\n    \n    # Question input and display area\n    question = st.text_input(\"Enter your question:\", value=st.session_state.question)\n    \n    if st.button(\"Ask\"):\n        # Generate the answer if question is provided\n        if question:\n            answer = answer_question(question, st.session_state.context)\n            st.session_state.answer = answer\n            st.write(\"Answer:\", answer)\n        else:\n            st.write(\"Please enter a question.\")\n    \n    # Button to ask another question\n    if st.button(\"Ask Another Question\"):\n        st.session_state.question = ''\n        st.session_state.answer = ''\n\n    # Button to go home and reset\n    if st.button(\"Reset\"):\n        go_home()\n","metadata":{"_uuid":"bd4bd821-034e-45a6-801e-c9c07eca80b8","_cell_guid":"3ce700a9-7bc6-4792-88f3-a6607d976637","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}